import struct

def encode_int(major, val):
    major_bits = major << 5
    if val < 24:
        return bytes([major_bits | val])
    elif val < 256:
        return bytes([major_bits | 24, val])
    elif val < 65536:
        return bytes([major_bits | 25]) + struct.pack(">H", val)
    elif val < 4294967296:
        return bytes([major_bits | 26]) + struct.pack(">I", val)
    else:
        return bytes([major_bits | 27]) + struct.pack(">Q", val)

def encode_cbor(obj):
    if obj is None:
        return b'\xf6'
    elif obj is False:
        return b'\xf4'
    elif obj is True:
        return b'\xf5'
    elif isinstance(obj, int):
        if obj >= 0:
            return encode_int(0, obj)
        else:
            return encode_int(1, -1 - obj)
    elif isinstance(obj, str):
        encoded = obj.encode('utf-8')
        return encode_int(3, len(encoded)) + encoded
    elif isinstance(obj, bytes):
        return encode_int(2, len(obj)) + obj
    elif isinstance(obj, list) or isinstance(obj, tuple):
        header = encode_int(4, len(obj))
        return header + b''.join(encode_cbor(x) for x in obj)
    elif isinstance(obj, dict):
        header = encode_int(5, len(obj))
        return header + b''.join(encode_cbor(k) + encode_cbor(v) for k, v in obj.items())
    else:
        raise ValueError(f"Unsupported type: {type(obj)}")

# Decode CBOR for inspecting requests
def decode_cbor(data, pos=0):
    if pos >= len(data):
        raise ValueError("EOF")
    b = data[pos]
    major = b >> 5
    info = b & 0x1f
    pos += 1

    if info < 24:
        val = info
    elif info == 24:
        val = data[pos]; pos += 1
    elif info == 25:
        val = struct.unpack(">H", data[pos:pos+2])[0]; pos += 2
    elif info == 26:
        val = struct.unpack(">I", data[pos:pos+4])[0]; pos += 4
    elif info == 27:
        val = struct.unpack(">Q", data[pos:pos+8])[0]; pos += 8
    else:
        val = None

    if major == 0:
        return val, pos
    elif major == 1:
        return -1 - val, pos
    elif major == 2:
        res = data[pos:pos+val]; pos += val
        return res, pos
    elif major == 3:
        res = data[pos:pos+val].decode('utf-8'); pos += val
        return res, pos
    elif major == 4:
        arr = []
        for _ in range(val):
            elem, pos = decode_cbor(data, pos)
            arr.append(elem)
        return arr, pos
    elif major == 5:
        m = {}
        for _ in range(val):
            k, pos = decode_cbor(data, pos)
            v, pos = decode_cbor(data, pos)
            m[k] = v
        return m, pos
    elif major == 7:
        if info == 20: return False, pos
        if info == 21: return True, pos
        if info == 22: return None, pos
    raise ValueError(f"Unknown CBOR major {major} info {info}")

# Test encoder & decoder
data = {"StatusResponse": {"tasks": {}, "groups": {"default": {"name": "default", "status": "Running", "parallel_tasks": 1}}}}
encoded = encode_cbor(data)
decoded, _ = decode_cbor(encoded)
print("Decoded matches:", data == decoded)
