        return bytes([major_bits | 25]) + struct.pack(">H", val)
    elif val < 4294967296:
        return bytes([major_bits | 26]) + struct.pack(">I", val)
    else:
        return bytes([major_bits | 27]) + struct.pack(">Q", val)

class CBORTag:
    def __init__(self, tag, value):
        self.tag = tag
        self.value = value
    def __repr__(self):
        return f"CBORTag({self.tag}, {self.value!r})"

def encode_cbor(obj):
    if obj is None:
        return b'\xf6'
    elif obj is False:
        return b'\xf4'
    elif obj is True:
        return b'\xf5'
    elif isinstance(obj, int):
        if obj >= 0:
            return encode_int(0, obj)
        else:
            return encode_int(1, -1 - obj)
    elif isinstance(obj, str):
        encoded = obj.encode('utf-8')
        return encode_int(3, len(encoded)) + encoded
    elif isinstance(obj, bytes):
        return encode_int(2, len(obj)) + obj
    elif isinstance(obj, CBORTag):
        return encode_int(6, obj.tag) + encode_cbor(obj.value)
    elif isinstance(obj, (list, tuple)):
        header = encode_int(4, len(obj))
        return header + b''.join(encode_cbor(x) for x in obj)
    elif isinstance(obj, dict):
        header = encode_int(5, len(obj))
        return header + b''.join(encode_cbor(k) + encode_cbor(v) for k, v in obj.items())
    else:
        raise ValueError(f"Unsupported CBOR type: {type(obj)}")

def decode_cbor(data, pos=0):
    if pos >= len(data):
        raise ValueError("CBOR EOF")
    b = data[pos]
    major = b >> 5
    info = b & 0x1f
    pos += 1

    if info < 24:
        val = info
    elif info == 24:
        val = data[pos]; pos += 1
    elif info == 25:
        val = struct.unpack(">H", data[pos:pos+2])[0]; pos += 2
    elif info == 26:
        val = struct.unpack(">I", data[pos:pos+4])[0]; pos += 4
    elif info == 27:
        val = struct.unpack(">Q", data[pos:pos+8])[0]; pos += 8
    elif info == 31: # Indefinite length (not typically used in serde_cbor)
        val = None
    else:
        raise ValueError(f"Invalid CBOR additional info {info}")

    if major == 0:
        return val, pos
    elif major == 1:
        return -1 - val, pos
    elif major == 2:
        res = data[pos:pos+val]; pos += val
        return res, pos
    elif major == 3:
        res = data[pos:pos+val].decode('utf-8', errors='replace'); pos += val
        return res, pos
    elif major == 4:
        arr = []
        for _ in range(val):
            elem, pos = decode_cbor(data, pos)
            arr.append(elem)
        return arr, pos
    elif major == 5:
        m = {}
        for _ in range(val):
            k, pos = decode_cbor(data, pos)
            v, pos = decode_cbor(data, pos)
            m[k] = v
        return m, pos
    elif major == 6:
        inner, pos = decode_cbor(data, pos)
        return CBORTag(val, inner), pos
    elif major == 7:
        if info == 20: return False, pos
        if info == 21: return True, pos
        if info == 22: return None, pos
        if info < 24: return val, pos
    raise ValueError(f"Unknown CBOR major {major} info {info}")
