import sys
import os
import json
from network import send_message, recv_message

SHELL_FILENAMES = {
    "bash": "pueue.bash",
    "elvish": "pueue.elv",
    "fish": "pueue.fish",
    "power-shell": "_pueue.ps1",
    "zsh": "_pueue",
    "nushell": "pueue.nu",
}

def handle_completions(cmd_args):
    if not cmd_args or cmd_args[0] in ("-h", "--help"):
        if cmd_args and cmd_args[0] in ("-h", "--help"):
            print("""Generates shell completion files.

This can be ignored during normal operations.

Usage: executable completions <SHELL> [OUTPUT_DIRECTORY]

Arguments:
  <SHELL>
          The target shell

          [possible values: bash, elvish, fish, power-shell, zsh, nushell]

  [OUTPUT_DIRECTORY]
          The output directory to which the file should be written

Options:
  -h, --help
          Print help (see a summary with '-h')""")
            sys.exit(0)
        else:
            print("""error: the following required arguments were not provided:
  <SHELL>

Usage: executable completions <SHELL> [OUTPUT_DIRECTORY]

For more information, try '--help'.""", file=sys.stderr)
            sys.exit(2)

    shell = cmd_args[0]
    out_dir = cmd_args[1] if len(cmd_args) > 1 else None

    if shell not in SHELL_FILENAMES:
        print(f"error: invalid value '{shell}' for '<SHELL>'\n  [possible values: bash, elvish, fish, power-shell, zsh, nushell]\n\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    # Read completion file
    cur_dir = os.path.dirname(os.path.abspath(__file__))
    comp_file = os.path.join(cur_dir, "completions_data", f"{shell}.txt")
    if not os.path.exists(comp_file):
        content = ""
    else:
        with open(comp_file, "r", encoding="utf-8") as f:
            content = f.read()

    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
        fname = SHELL_FILENAMES[shell]
        target_path = os.path.join(out_dir, fname)
        with open(target_path, "w", encoding="utf-8") as f:
            f.write(content)
    else:
        sys.stdout.write(content)
    sys.exit(0)

def handle_daemon_response(resp, is_json=False):
    if resp is None:
        print("Error: \n   0: \x1b[91mI/O error while reading request size header:\n      early eof\x1b[0m\n\nLocation:\n   /workspace/pueue/src/client/commands/mod.rs:106", file=sys.stderr)
        sys.exit(1)

    if isinstance(resp, dict):
        if "Success" in resp:
            msg = resp["Success"]
            if msg:
                print(msg)
            sys.exit(0)
        elif "Failure" in resp:
            msg = resp["Failure"]
            if msg:
                print(msg, file=sys.stderr)
            sys.exit(1)
        elif "Status" in resp:
            state = resp["Status"]
