#!/usr/bin/env python3
import sys
import os

# Add src/ directory to python path
cur_dir = os.path.dirname(os.path.abspath(__file__))
if cur_dir not in sys.path:
    sys.path.insert(0, cur_dir)

from cli import parse_args, HELP_TEXT, SHORT_HELP
from config import load_config, get_secret_path, get_socket_path
from network import connect_and_handshake, send_message, recv_message
from commands import handle_completions, handle_daemon_response

def main():
    parsed = parse_args(sys.argv)
    cmd_args = parsed["cmd_args"]

    if not cmd_args:
        print(SHORT_HELP)
        sys.exit(0)

    subcmd = cmd_args[0]

    # Handle help/version subcommands
    if subcmd in ("-V", "--version"):
        print("pueue 4.0.4")
        sys.exit(0)
    elif subcmd in ("-h", "--help", "help"):
        if len(cmd_args) > 1 and cmd_args[1] not in ("-h", "--help"):
            # Print subcommand help
            target_cmd = cmd_args[1]
            print(f"Help for {target_cmd}")
            sys.exit(0)
        else:
            print(HELP_TEXT)
            sys.exit(0)

    if subcmd == "completions":
        handle_completions(cmd_args[1:])

    # Load configuration
    cfg, cfg_path = load_config(parsed["config_path"])
    secret_path = get_secret_path(cfg)
    socket_path = get_socket_path(cfg)

    # Connect to daemon
    sock = connect_and_handshake(cfg, secret_path, socket_path)

    # Build request CBOR payload
    req_obj = build_request(subcmd, cmd_args[1:])
    is_json = "-j" in cmd_args or "--json" in cmd_args

    send_message(sock, req_obj)
    resp = recv_message(sock)
    sock.close()

    # Handle print task id flag for 'add' command
    if subcmd == "add" and ("-p" in cmd_args or "--print-task-id" in cmd_args):
        if isinstance(resp, dict) and "Success" in resp:
            # Extract task ID from success message if possible
            msg = resp["Success"]
            import re
            m = re.search(r'\b(\d+)\b', msg)
            if m:
                print(m.group(1))
                sys.exit(0)

    handle_daemon_response(resp, is_json=is_json)

def build_request(subcmd, args):
    if subcmd == "status":
        return "Status"
    elif subcmd == "add":
        if not args or args[0] in ("-h", "--help"):
            if args and args[0] in ("-h", "--help"):
                print("Usage: executable add [OPTIONS] <COMMAND>...")
                sys.exit(0)
            else:
                print("error: the following required arguments were not provided:\n  <COMMAND>...\n\nUsage: executable add <COMMAND>...\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)

        # Parse add options
        command_parts = []
        working_directory = os.getcwd()
        escape = False
        immediate = False
        stashed = False
        delay = None
        group = "default"
        after = []
        priority = None
        label = None
        print_task_id = False

        i = 0
        while i < len(args):
            a = args[i]
            if a in ("-w", "--working-directory"):
                if i + 1 < len(args): working_directory = args[i+1]; i += 2; continue
            elif a.startswith("--working-directory="): working_directory = a.split("=", 1)[1]; i += 1; continue
            elif a in ("-e", "--escape"): escape = True; i += 1; continue
            elif a in ("-i", "--immediate"): immediate = True; i += 1; continue
            elif a in ("-s", "--stashed"): stashed = True; i += 1; continue
            elif a in ("-d", "--delay"):
                if i + 1 < len(args): delay = args[i+1]; i += 2; continue
            elif a.startswith("--delay="): delay = a.split("=", 1)[1]; i += 1; continue
            elif a in ("-g", "--group"):
                if i + 1 < len(args): group = args[i+1]; i += 2; continue
            elif a.startswith("--group="): group = a.split("=", 1)[1]; i += 1; continue
            elif a in ("-a", "--after"):
                if i + 1 < len(args):
                    try: after.append(int(args[i+1]))
                    except ValueError: pass
                    i += 2; continue
            elif a in ("-o", "--priority"):
                if i + 1 < len(args):
                    try: priority = int(args[i+1])
                    except ValueError: pass
                    i += 2; continue
            elif a in ("-l", "--label"):
                if i + 1 < len(args): label = args[i+1]; i += 2; continue
            elif a in ("-p", "--print-task-id"): print_task_id = True; i += 1; continue
            else:
                command_parts.append(a)
                i += 1

        cmd_str = " ".join(command_parts)
        return {
            "Add": {
                "command": cmd_str,
                "path": working_directory,
                "envs": dict(os.environ),
                "start_immediately": immediate,
                "stashed": stashed,
                "group": group,
                "enqueue_at": delay,
                "dependencies": after,
                "priority": priority,
                "label": label
            }
        }
    elif subcmd == "remove":
        if not args:
            print("error: the following required arguments were not provided:\n  <TASK_IDS>...\n\nUsage: executable remove <TASK_IDS>...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        task_ids = []
        for a in args:
            try: task_ids.append(int(a))
            except ValueError: pass
        return {"Remove": task_ids}
    elif subcmd == "switch":
        if len(args) < 2:
            req = "<TASK_ID_1>" if not args else "<TASK_ID_2>"
            print(f"error: the following required arguments were not provided:\n  {req}\n\nUsage: executable switch <TASK_ID_1> <TASK_ID_2>\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        return {"Switch": {"task_id_1": int(args[0]), "task_id_2": int(args[1])}}
    elif subcmd == "stash":
        target = parse_target(args)
        delay = parse_opt_value(args, "-d", "--delay")
        return {"Stash": {"tasks": target, "enqueue_at": delay}}
    elif subcmd == "enqueue":
        target = parse_target(args)
        delay = parse_opt_value(args, "-d", "--delay")
        return {"Enqueue": {"tasks": target, "enqueue_at": delay}}
    elif subcmd == "start":
        target = parse_target(args)
        return {"Start": {"tasks": target}}
    elif subcmd == "pause":
        target = parse_target(args)
        wait = "-w" in args or "--wait" in args
        return {"Pause": {"tasks": target, "wait": wait}}
    elif subcmd == "kill":
        target = parse_target(args)
        sig = parse_opt_value(args, "-s", "--signal")
        return {"Kill": {"tasks": target, "signal": sig}}
    elif subcmd == "send":
        if len(args) < 2:
            req = "<TASK_ID>" if not args else "<INPUT>"
            print(f"error: the following required arguments were not provided:\n  {req}\n\nUsage: executable send <TASK_ID> <INPUT>\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        return {"Send": {"task_id": int(args[0]), "input": args[1]}}
    elif subcmd == "clean":
        succ = "-s" in args or "--successful-only" in args
        group = parse_opt_value(args, "-g", "--group")
        return {"Clean": {"successful_only": succ, "group": group}}
    elif subcmd == "group":
        if not args:
            return {"Group": "List"}
        sub = args[0]
        if sub == "add":
            if len(args) < 2:
                print("error: the following required arguments were not provided:\n  <NAME>\n\nUsage: executable group add <NAME>\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            par = int(args[2]) if len(args) > 2 and args[2].isdigit() else None
            return {"Group": {"Add": {"name": args[1], "parallel_tasks": par}}}
        elif sub == "remove":
            if len(args) < 2:
                print("error: the following required arguments were not provided:\n  <NAME>\n\nUsage: executable group remove <NAME>\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            return {"Group": {"Remove": args[1]}}
        return {"Group": "List"}
    elif subcmd == "parallel":
        group = parse_opt_value(args, "-g", "--group") or "default"
        num = 0
        for a in args:
            if a.isdigit():
                num = int(a)
                break
        return {"Parallel": {"parallel_tasks": num, "group": group}}
    elif subcmd == "shutdown":
        return {"DaemonShutdown": "Graceful"}
    elif subcmd == "log":
        target = parse_target(args)
        lines = parse_opt_value(args, "-l", "--lines")
        lines_int = int(lines) if lines and lines.isdigit() else 15
        send_logs = "-f" in args or "--full" in args
        return {"Log": {"tasks": target, "send_logs": send_logs, "lines": lines_int}}
    elif subcmd == "follow":
        return "Status"
    elif subcmd == "wait":
        return "Status"
    elif subcmd == "reset":
        return "Status"
    elif subcmd == "restart":
        task_ids = []
        for a in args:
            if a.isdigit():
                task_ids.append(int(a))
        return {"Restart": {"tasks": task_ids}}

    return "Status"

def parse_target(args):
    task_ids = []
    group = None
    all_flag = False

    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-g", "--group"):
            if i + 1 < len(args): group = args[i+1]; i += 2; continue
        elif a.startswith("--group="): group = a.split("=", 1)[1]; i += 1; continue
        elif a in ("-a", "--all"): all_flag = True; i += 1; continue
        elif a.isdigit():
            task_ids.append(int(a))
            i += 1
        else:
            i += 1

    if task_ids:
        return {"TaskIds": task_ids}
    elif group:
        return {"Group": group}
    elif all_flag:
        return "All"
    else:
        return {"Group": "default"}

def parse_opt_value(args, short_flag, long_flag):
    i = 0
    while i < len(args):
        a = args[i]
        if a in (short_flag, long_flag):
            if i + 1 < len(args): return args[i+1]
        elif a.startswith(long_flag + "="):
            return a.split("=", 1)[1]
        i += 1
    return None

if __name__ == "__main__":
